import React, { useCallback, useRef, useState } from 'react';
import { HostEvent } from '@thoughtspot/visual-embed-sdk';
import { SearchEmbed, SpotterEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { THOUGHTSPOT_MODEL_ID, DATABOT_ICON_URL, VIEWPORT_LESS_TOP_HEADER } from '../config/thoughtspot';
import { useTier } from '../config/TierContext';
import { formatThoughtSpotEmbedError } from '../utils/thoughtspotErrors';

type TabId = 'dataBot' | 'explore';

const PRIMARY = '#1D3FA8';
const LABEL_PURPLE = '#1D3FA8';

function TabCard({
  active,
  title,
  subtitle,
  onClick,
}: {
  active: boolean;
  title: string;
  subtitle: string;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      style={{
        flex: '1 1 160px',
        minWidth: 140,
        textAlign: 'left',
        padding: '1.25rem 1.35rem',
        borderRadius: 12,
        border: active ? `1px solid ${PRIMARY}` : '1px solid #E5E7EB',
        backgroundColor: active ? PRIMARY : '#ffffff',
        color: active ? '#ffffff' : LABEL_PURPLE,
        cursor: 'pointer',
        transition: 'background-color 0.15s ease, border-color 0.15s ease',
      }}
    >
      <div style={{ fontWeight: 700, fontSize: 16, marginBottom: 4 }}>{title}</div>
      <div
        style={{
          fontSize: 13,
          fontWeight: 400,
          color: active ? 'rgba(255,255,255,0.85)' : '#6B7280',
        }}
      >
        {subtitle}
      </div>
    </button>
  );
}

function DataBotUpgrade({ onUpgrade }: { onUpgrade: () => void }) {
  return (
    <div
      style={{
        backgroundColor: '#fff',
        borderRadius: 12,
        border: '1px solid #E5E7EB',
        padding: '3rem 2rem',
        textAlign: 'center',
        maxWidth: 480,
        margin: '2rem auto',
      }}
    >
      <h2 style={{ fontSize: 20, fontWeight: 700, color: LABEL_PURPLE, margin: '0 0 8px' }}>Data Bot</h2>
      <p style={{ fontSize: 14, color: '#6B7280', lineHeight: 1.6, margin: '0 0 1.25rem' }}>
        Ask questions in plain English against your worksheet. Upgrade to Pro to enable Data Bot and related AI
        actions in the embed.
      </p>
      <button
        type="button"
        onClick={onUpgrade}
        style={{
          backgroundColor: PRIMARY,
          color: '#fff',
          border: 'none',
          padding: '10px 28px',
          borderRadius: 8,
          fontSize: 14,
          fontWeight: 600,
          cursor: 'pointer',
        }}
      >
        Upgrade to Pro
      </button>
    </div>
  );
}

export default function Analytics() {
  const [tab, setTab] = useState<TabId>('dataBot');
  const { hiddenActions, disabledActions, spotterEnabled, setTier } = useTier();
  const spotterRef = useRef<any>(null);
  const searchRef = useRef<any>(null);

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    console.error('[ThoughtSpot Analytics]', formatThoughtSpotEmbedError(err), err);
  }, []);

  const handleRefresh = () => {
    try {
      if (tab === 'dataBot') spotterRef.current?.trigger(HostEvent.Reload);
      else searchRef.current?.trigger(HostEvent.Reload);
    } catch (e) {
      console.warn('Reload trigger', e);
    }
  };

  const section =
    tab === 'dataBot'
      ? { title: 'Data Bot', subtitle: 'Ask questions in plain English against your dataset.' }
      : { title: 'Explore', subtitle: 'Build your own analysis from the worksheet.' };

  return (
    <div
      style={{
        minHeight: VIEWPORT_LESS_TOP_HEADER,
        display: 'flex',
        flexDirection: 'column',
        backgroundColor: '#F9FAFB',
        overflowX: 'hidden',
        overflowY: 'auto',
      }}
    >
      <div
        style={{
          position: 'sticky',
          top: 0,
          zIndex: 30,
          flexShrink: 0,
          borderBottom: '1px solid #E5E7EB',
        }}
      >
        {/* Blue title banner */}
        <div style={{ backgroundColor: '#1D3FA8', padding: '1.75rem 2.5rem 1.25rem' }}>
          <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', flexWrap: 'wrap', gap: 16 }}>
            <div>
              <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'rgba(255,255,255,0.55)', marginBottom: 6 }}>
                BST Media
              </div>
              <h1 style={{ fontSize: 28, fontWeight: 800, color: '#ffffff', margin: 0 }}>Explore & Ask AI</h1>
              <p style={{ fontSize: 14, color: 'rgba(255,255,255,0.75)', margin: '6px 0 0', maxWidth: 520 }}>
                Ask questions in plain English with Data Bot, or build your own analysis with Search.
              </p>
            </div>
            <div style={{ display: 'flex', gap: 10, alignItems: 'center', flexShrink: 0 }}>
              <button
                type="button"
                onClick={handleRefresh}
                style={{
                  padding: '9px 18px',
                  borderRadius: 8,
                  border: '1px solid rgba(255,255,255,0.4)',
                  background: 'rgba(255,255,255,0.15)',
                  color: '#ffffff',
                  fontSize: 14,
                  fontWeight: 500,
                  cursor: 'pointer',
                }}
              >
                Refresh
              </button>
            </div>
          </div>
        </div>

        {/* Tab cards on light background */}
        <div style={{ backgroundColor: '#f4f6fb', padding: '0.85rem 2.5rem' }}>
          <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', alignItems: 'stretch' }}>
            <TabCard
              active={tab === 'dataBot'}
              title="Data Bot"
              subtitle="Ask questions in plain English"
              onClick={() => { setTab('dataBot'); }}
            />
            <TabCard
              active={tab === 'explore'}
              title="Explore"
              subtitle="Build your own analysis"
              onClick={() => { setTab('explore'); }}
            />
          </div>
        </div>
      </div>

      <div
        style={{
          padding: '0.75rem 2.5rem 1rem',
          flex: '1 1 auto',
          minHeight: 320,
          display: 'flex',
          flexDirection: 'column',
        }}
      >
        <h2 style={{ fontSize: 18, fontWeight: 700, color: LABEL_PURPLE, margin: '0 0 4px', flexShrink: 0 }}>{section.title}</h2>
        <p style={{ fontSize: 14, color: '#6B7280', margin: '0 0 0.75rem', flexShrink: 0 }}>{section.subtitle}</p>

        {tab === 'dataBot' && !spotterEnabled ? (
          <DataBotUpgrade onUpgrade={() => setTier('Pro')} />
        ) : (
          <div
            style={{
              flex: '1 1 auto',
              minHeight: 480,
              backgroundColor: '#ffffff',
              borderRadius: 12,
              border: '1px solid #E5E7EB',
              overflow: 'hidden',
              display: 'flex',
              flexDirection: 'column',
            }}
          >
            {tab === 'dataBot' && spotterEnabled && (
              <SpotterEmbed
                ref={spotterRef}
                worksheetId={THOUGHTSPOT_MODEL_ID}
                onError={onError}
                hideSampleQuestions
                customizations={{ iconSpriteUrl: DATABOT_ICON_URL }}
                style={{ width: '100%', height: '100%', flex: 1, minHeight: 400, border: 'none' }}
              />
            )}
            {tab === 'explore' && (
              <SearchEmbed
                ref={searchRef}
                dataSource={THOUGHTSPOT_MODEL_ID}
                hiddenActions={hiddenActions}
                disabledActions={disabledActions}
                onError={onError}
                style={{ width: '100%', height: '100%', flex: 1, minHeight: 400, border: 'none' }}
              />
            )}
          </div>
        )}
      </div>
    </div>
  );
}
